-- ============================================================================
-- RMIMS 6-MONTH 2026 DAILY DATASET SEEDER (March 1, 2026 - September 2, 2026)
-- Clean, consistent, realistic daily bakery operational data.
-- ============================================================================

DO $$
DECLARE
    v_mat_id UUID;
    v_m1 UUID;
    v_m2 UUID;
    v_m3 UUID;
    v_m4 UUID;
    v_m5 UUID;
    v_m6 UUID;
    v_m7 UUID;
    v_m8 UUID;
