BEGIN
    -- 1. Clean existing records safely
    DELETE FROM public.material_disbursements;
    DELETE FROM public.stock_receipts;
    DELETE FROM public.raw_materials;

    -- 2. Insert Raw Materials Master Catalog
    VALUES ('RM-001', 'Bread Flour', 'High-protein flour for artisan breads and pandesal', 'kg', 100, 350, 3, 0)
