    VALUES ('RM-003', 'Refined White Sugar', 'Granulated pure cane sugar for bakery production', 'kg', 60, 250, 2, 0)
    RETURNING id INTO v_m3;
    VALUES ('RM-004', 'Salted Butter', 'Premium grade creamery salted butter for croissants and pastries', 'kg', 40, 150, 2, 0)
    RETURNING id INTO v_m4;
    VALUES ('RM-005', 'Fresh Eggs', 'Grade-A fresh farm eggs for batter and dough binding', 'pcs', 150, 600, 1, 0)
    RETURNING id INTO v_m5;
    VALUES ('RM-006', 'Whole Milk', 'Pasteurized whole milk for enriched doughs and creams', 'L', 30, 120, 1, 0)
    RETURNING id INTO v_m6;
    VALUES ('RM-007', 'Instant Dry Yeast', 'Fast-acting dry yeast for bread fermentation', 'kg', 15, 60, 4, 0)
    RETURNING id INTO v_m7;
    VALUES ('RM-008', 'Iodized Salt', 'Fine table salt for flavor balance and gluten strengthening', 'kg', 20, 80, 3, 0)
