    RETURNING id INTO v_m10;

    -- 3. Insert 6-Month Daily Transactions (March 1, 2026 - September 2, 2026)


    -- 4. Set Authoritative Final Stock Balances
    UPDATE public.raw_materials SET current_stock = 226.38 WHERE id = v_m1;
    UPDATE public.raw_materials SET current_stock = 614.19 WHERE id = v_m2;
    UPDATE public.raw_materials SET current_stock = 987.25 WHERE id = v_m3;
    UPDATE public.raw_materials SET current_stock = 466.63 WHERE id = v_m4;
    UPDATE public.raw_materials SET current_stock = 1127.99 WHERE id = v_m5;
    UPDATE public.raw_materials SET current_stock = 314.3 WHERE id = v_m6;
    UPDATE public.raw_materials SET current_stock = 687.84 WHERE id = v_m7;
    UPDATE public.raw_materials SET current_stock = 910.56 WHERE id = v_m8;
    UPDATE public.raw_materials SET current_stock = 306.04 WHERE id = v_m9;
    UPDATE public.raw_materials SET current_stock = 298.67 WHERE id = v_m10;

    RAISE NOTICE 'Successfully seeded 6-month 2026 daily bakery dataset!';
END $$;
